# catch_at_length ----
## Setup ----
# cal_data, a 3-year, 4-length-bin catch-at-length model, and the values it
# is made from (cal_years, cal_lengths, cal_weights and cal_terminal_molt)
# are in helper-catch-at-length.R.
cal_frame <- FIMSFrame(cal_data)
cal_default_parameters <- setup_default_parameters(
  cal_frame,
  model_type = "CatchAtLength"
)

## IO correctness ----
test_that("`linear_gamma_increment_growth()` produces a valid upper-triangular transition matrix", {
  length_edges <- c(25, 30, 35, 40, 45)
  length_midpoints <- c(27.5, 32.5, 37.5, 42.5)
  growth_out <- FIMS:::linear_gamma_increment_growth(
    length_edges = length_edges,
    length_midpoints = length_midpoints,
    observed_premolt_lengths = c(27.5, 32.5),
    growth_intercept = 5.0,
    growth_slope = 0.1,
    growth_scale = 0.75
  )
  transition <- growth_out[["growth_transition"]]

  #' @description Test that the growth transition matrix has 1 row and column per length bin.
  expect_equal(
    object = dim(transition),
    expected = c(4L, 4L)
  )
  #' @description Test that each row of the growth transition matrix sums to 1.
  expect_equal(
    object = rowSums(transition),
    expected = rep(1, 4),
    tolerance = 1e-12
  )
  #' @description Test that entries below the diagonal of the growth transition matrix are 0 (no shrinkage below the premolt bin).
  expect_equal(
    object = transition[lower.tri(transition)],
    expected = rep(0, 6)
  )
  #' @description Test that expected growth increments at observed premolt lengths equal intercept + slope * length.
  expect_equal(
    object = growth_out[["growth_increment_expected"]],
    expected = 5.0 + 0.1 * c(27.5, 32.5),
    tolerance = 1e-12
  )
})

test_that("`gamma_length_recruitment_distribution()` sums to 1 and zeroes bins above max_recruit_length_bin", {
  length_edges <- c(25, 30, 35, 40, 45)
  rec_dist <- FIMS:::gamma_length_recruitment_distribution(
    length_edges = length_edges,
    recruit_gamma_shape = 32.5,
    recruit_gamma_scale = 1.0,
    max_recruit_length_bin = 3L
  )

  #' @description Test that the recruitment length distribution sums to 1.
  expect_equal(
    object = sum(rec_dist),
    expected = 1.0,
    tolerance = 1e-12
  )
  #' @description Test that bins above max_recruit_length_bin receive 0 recruitment proportion.
  expect_equal(
    object = rec_dist[4],
    expected = 0
  )
})

test_that("`process_steps()` counts steps by length in length bins, not bin widths", {
  # The last bin is twice as wide as the others.
  target_rows <- tibble::tibble(
    timing = NA_real_,
    age = NA_real_,
    length = c(25, 30, 35, 45)
  )
  #' @description Test that adjacent length bins of different widths are 1 step apart, so a process by length keeps its plain form.
  expect_null(
    FIMS:::process_steps(target_rows, rep(TRUE, 4), "logit_sel_at_length")
  )
  #' @description Test that a constant length bin between 2 estimated bins makes a step of 2 bins.
  expect_equal(
    object = FIMS:::process_steps(
      target_rows, c(TRUE, FALSE, TRUE, TRUE), "logit_sel_at_length"
    ),
    expected = c(2, 1)
  )
})

## Edge handling ----
test_that("`linear_gamma_increment_growth()` and `gamma_length_recruitment_distribution()` work from a length edge of 0", {
  # The gamma CDF is 0 at 0, so each bin holds the gamma probability between
  # its edges, divided by the probability over the bins that can be entered.
  length_edges <- c(0, 50, 100, 150)
  growth_out <- FIMS:::linear_gamma_increment_growth(
    length_edges = length_edges,
    length_midpoints = c(25, 75, 125),
    observed_premolt_lengths = numeric(0),
    growth_intercept = 15,
    growth_slope = -0.05,
    growth_scale = 0.75
  )
  # From the first bin, the mean postmolt length is 25 + 15 - 0.05 * 25.
  first_bin_shape <- (25 + 15 - 0.05 * 25) / 0.75
  first_bin_cdf <- stats::pgamma(length_edges, first_bin_shape, scale = 0.75)
  #' @description Test that the growth transition from the first length bin, which starts at 0, is the gamma probability in each bin with shape (L + intercept + slope * L) / scale.
  expect_equal(
    object = growth_out[["growth_transition"]][1, ],
    expected = diff(first_bin_cdf) / first_bin_cdf[4],
    tolerance = 1e-12
  )
  recruit_cdf <- stats::pgamma(length_edges, 75 / 10, scale = 10)
  #' @description Test that the recruitment length distribution from a first length edge of 0 is the gamma probability in each bin with shape mean / scale.
  expect_equal(
    object = FIMS:::gamma_length_recruitment_distribution(
      length_edges = length_edges,
      recruit_gamma_shape = 75,
      recruit_gamma_scale = 10,
      max_recruit_length_bin = 3L
    ),
    expected = diff(recruit_cdf) / recruit_cdf[4],
    tolerance = 1e-12
  )
})

test_that("`catch_at_length()` conserves total numbers when M = F = 0 and recruitment is 0", {
  zero_mortality_parameters <- cal_default_parameters |>
    dplyr::mutate(
      value = dplyr::case_when(
        .data[["module_name"]] == "Population" &
          .data[["label"]] == "log_M" ~ -200,
        .data[["module_name"]] == "Population" &
          .data[["label"]] == "log_M_immature_offset" ~ 0,
        .data[["module_name"]] == "Fleet" &
          .data[["label"]] == "log_Fmort" ~ -200,
        .data[["module_name"]] == "Recruitment" &
          .data[["label"]] == "log_r" ~ -200,
        .default = .data[["value"]]
      )
    )
  report <- zero_mortality_parameters |>
    initialize_fims(data = cal_frame) |>
    fit_fims(optimize = FALSE) |>
    get_report()

  n_immature <- matrix(
    report[["numbers_at_length_immature"]][[1]],
    nrow = length(cal_years) + 1,
    ncol = length(cal_lengths),
    byrow = TRUE
  )
  n_mature <- matrix(
    report[["numbers_at_length_mature"]][[1]],
    nrow = length(cal_years) + 1,
    ncol = length(cal_lengths),
    byrow = TRUE
  )
  total_by_year <- rowSums(n_immature + n_mature)

  #' @description Test that total numbers across immature and mature stages are conserved across years when M = F = 0 and recruitment is 0.
  expect_equal(
    object = total_by_year,
    expected = rep(total_by_year[1], length(cal_years) + 1),
    tolerance = 1e-10
  )
  #' @description Test that mature numbers at every length bin never decrease when M = F = 0 (mature crabs never return to immature).
  expect_true(
    object = all(diff(n_mature) >= -1e-10)
  )
})

test_that("`catch_at_length()` satisfies catch decomposition and spawning biomass identities", {
  fit <- cal_default_parameters |>
    initialize_fims(data = cal_frame) |>
    fit_fims(optimize = FALSE)
  report <- get_report(fit)

  #' @description Test that retained plus discarded catch numbers at length equal total catch numbers at length for the pot fleet.
  expect_equal(
    object = report[["catch_retained_numbers_at_length"]][[1]] +
      report[["catch_discarded_numbers_at_length"]][[1]],
    expected = report[["catch_numbers_at_length"]][[1]],
    tolerance = 1e-12
  )
  #' @description Test that retained plus discarded catch weight at length equals total catch weight at length for the pot fleet.
  expect_equal(
    object = report[["catch_retained_weight_at_length"]][[1]] +
      report[["catch_discarded_weight_at_length"]][[1]],
    expected = report[["catch_weight_at_length"]][[1]],
    tolerance = 1e-12
  )
  #' @description Test that annual retained plus discarded catch weight equals annual total catch weight for the pot fleet.
  expect_equal(
    object = report[["catch_retained_expected"]][[1]] +
      report[["catch_discarded_expected"]][[1]],
    expected = report[["catch_weight"]][[1]],
    tolerance = 1e-12
  )

  # Spawning biomass is mature numbers after season 2 times weight at length.
  n_mature <- matrix(
    report[["numbers_at_length_mature"]][[1]],
    nrow = length(cal_years) + 1,
    ncol = length(cal_lengths),
    byrow = TRUE
  )[seq_along(cal_years), , drop = FALSE]
  m_mature <- matrix(
    report[["mortality_M_mature"]][[1]],
    nrow = length(cal_years),
    ncol = length(cal_lengths),
    byrow = TRUE
  )
  f_total <- matrix(
    report[["mortality_F"]][[1]],
    nrow = length(cal_years),
    ncol = length(cal_lengths),
    byrow = TRUE
  )
  mature_after_season2 <- n_mature * exp(-(0.62 + 0.01) * m_mature - f_total)
  expected_ssb <- as.vector(mature_after_season2 %*% cal_weights)

  #' @description Test that spawning_biomass equals mature numbers after season 2 times weight at length.
  expect_equal(
    object = report[["spawning_biomass"]][[1]],
    expected = expected_ssb,
    tolerance = 1e-12
  )
})

test_that("`LengthSpecific` selectivity and `robust_normal_multinomial()` match analytical formulas", {
  logit_values <- c(-2, -0.5, 0.5, 2)
  sel_params <- cal_default_parameters |>
    dplyr::filter(
      !(.data[["module_name"]] == "Selectivity" &
        .data[["fleet"]] == "survey_fleet")
    ) |>
    dplyr::bind_rows(
      setup_default_Selectivity(
        cal_frame,
        fleet = "survey_fleet",
        module_type = "LengthSpecific"
      ) |>
        dplyr::mutate(value = logit_values)
    )
  report <- sel_params |>
    initialize_fims(data = cal_frame) |>
    fit_fims(optimize = FALSE) |>
    get_report()
  survey_realized_sel <- report[["index_numbers_at_length"]][[2]][seq_along(cal_lengths)] /
    report[["numbers_at_length_mature"]][[1]][seq_along(cal_lengths)]

  #' @description Test that LengthSpecific selectivity in the first year equals plogis(logit_sel_at_length).
  expect_equal(
    object = survey_realized_sel,
    expected = stats::plogis(logit_values),
    tolerance = 1e-12
  )

  # Direct check of robust_normal_multinomial_lpdf() against the GMACS formula.
  obs_counts <- c(10, 20, 30, 40)
  pred_probs <- c(0.15, 0.25, 0.30, 0.30)
  nsamp <- sum(obs_counts)
  offset <- 1e-8
  obs_p <- (obs_counts / nsamp + offset) / sum(obs_counts / nsamp + offset)
  pred_p <- (pred_probs + offset) / sum(pred_probs + offset)
  nbin <- length(obs_counts)
  var_term <- 0.1 / nbin + obs_p * (1 - obs_p)
  scaled_sq <- 0.5 * (pred_p - obs_p)^2 / var_term
  hand_loglik <- sum(
    log(exp(-nsamp * scaled_sq) + 0.01) - 0.5 * log(var_term / nsamp)
  )

  #' @description Test that robust_normal_multinomial_lpdf() matches the GMACS robust normal approximation to the multinomial log-likelihood.
  expect_equal(
    object = sum(FIMS:::robust_normal_multinomial_lpdf(
      matrix(obs_counts, nrow = 1),
      matrix(pred_probs, nrow = 1)
    )),
    expected = hand_loglik,
    tolerance = 1e-12
  )
})

test_that("`add_process()` by length and `add_priors()` with transform work in `CatchAtLength`", {
  logit_values <- c(-1.5, -0.5, 0.5, 1.5)
  rw_sd <- 0.5
  prior_means <- c(0.2, 0.4, 0.6, 0.8)
  prior_sds <- c(0.05, 0.05, 0.05, 0.05)

  custom_params <- cal_default_parameters |>
    dplyr::filter(
      !(.data[["module_name"]] == "Selectivity" &
        .data[["fleet"]] == "survey_fleet")
    ) |>
    dplyr::bind_rows(
      setup_default_Selectivity(
        cal_frame,
        fleet = "survey_fleet",
        module_type = "LengthSpecific"
      ) |>
        dplyr::mutate(value = logit_values)
    ) |>
    add_process(
      logit_sel_at_length ~ rw(1 | length),
      module_name = "Selectivity",
      fleet = "survey_fleet",
      estimation_type = "fixed_effects",
      sd = list(value = rw_sd, estimation_type = "constant")
    ) |>
    add_priors(
      logit_sel_at_length ~ normal(mean = prior_means, sd = prior_sds),
      module_name = "Selectivity",
      fleet = "survey_fleet",
      transform = "inv_logit"
    ) |>
    add_priors(
      log_M ~ normal(mean = 0.25, sd = 0.05),
      module_name = "Population",
      transform = "exp"
    )

  init <- initialize_fims(custom_params, cal_frame)
  fit <- fit_fims(init, optimize = FALSE)
  report <- get_report(fit)
  nll <- stats::setNames(
    report[["nll_components"]],
    FIMS:::label_nll_components(init[["model_data"]])
  )

  #' @description Test that the natural-scale inv_logit prior on logit_sel_at_length equals -sum(dnorm(plogis(x), mean, sd, log = TRUE)).
  expect_equal(
    object = unname(nll[1]),
    expected = -sum(stats::dnorm(
      stats::plogis(logit_values), prior_means, prior_sds,
      log = TRUE
    )),
    tolerance = 1e-12
  )
  #' @description Test that the natural-scale exp prior on log_M equals -dnorm(exp(log_M), mean, sd, log = TRUE).
  expect_equal(
    object = unname(nll[2]),
    expected = -stats::dnorm(0.25, 0.25, 0.05, log = TRUE),
    tolerance = 1e-12
  )
  #' @description Test that the rw(1 | length) process density on logit_sel_at_length equals -sum(dnorm(diff(x), 0, sd, log = TRUE)).
  expect_equal(
    object = unname(nll[4]),
    expected = -sum(stats::dnorm(diff(logit_values), 0, rw_sd, log = TRUE)),
    tolerance = 1e-12
  )

  estimates <- get_estimates(fit)
  #' @description Test that get_estimates() returns numbers_at_length_immature, numbers_at_length_mature, and spawning_biomass rows with length populated.
  expect_true(
    object = all(
      c(
        "numbers_at_length_immature",
        "numbers_at_length_mature",
        "spawning_biomass"
      ) %in% estimates[["label"]]
    ) && !all(is.na(estimates[["length"]]))
  )

  simulated <- simulate_fims(fit, number_of_simulations = 1)
  #' @description Test that simulate_fims() returns a valid simulated data tibble for a catch-at-length model.
  expect_s4_class(
    object = FIMSFrame(simulated[[1]][["data"]]),
    class = "FIMSFrame"
  )
})

test_that("`get_estimates()` reports catch-at-length expected composition counts as NA where there is no observation", {
  # pot_fleet's retained length composition for 2002 has -999 at length 30,
  # with the other bins rescaled to sum to 1. The robust normal skips that
  # year. survey_fleet has no retained length composition.
  missing_bin <- cal_data |>
    dplyr::mutate(
      is_2002_retained = type == "length_comp" & fleet == "pot_fleet" &
        timing == 2002 &
        grepl("lengthcomp_retained_proportion", uncertainty),
      observed = dplyr::case_when(
        is_2002_retained & length == 30 ~ -999,
        is_2002_retained ~
          observed / sum(observed[is_2002_retained & length != 30]),
        .default = observed
      )
    ) |>
    dplyr::select(-"is_2002_retained")
  missing_bin_frame <- FIMSFrame(missing_bin)
  counts <- setup_default_parameters(
    missing_bin_frame,
    model_type = "CatchAtLength"
  ) |>
    initialize_fims(data = missing_bin_frame) |>
    fit_fims(optimize = FALSE) |>
    get_estimates() |>
    dplyr::filter(.data[["label"]] %in% c(
      "lengthcomp_retained_expected", "lengthcomp_discarded_expected",
      "lengthcomp_immature_expected", "lengthcomp_mature_expected"
    ))
  retained <- dplyr::filter(
    counts,
    .data[["label"]] == "lengthcomp_retained_expected"
  )
  pot_2002 <- dplyr::filter(
    retained,
    .data[["fleet"]] == "pot_fleet", .data[["year"]] == 2002
  )
  survey <- dplyr::filter(retained, .data[["fleet"]] == "survey_fleet")
  #' @description Test that `get_estimates()` reports every bin of a skipped robust normal year of a catch-at-length composition as NA in `observed` and `estimated`.
  expect_true(all(is.na(c(pot_2002[["observed"]], pot_2002[["estimated"]]))))
  #' @description Test that `get_estimates()` reports the expected retained counts of a fleet without retained length compositions as NA.
  expect_equal(
    object = sum(is.na(survey[["estimated"]])),
    expected = length(cal_years) * length(cal_lengths)
  )
  #' @description Test that `get_estimates()` keeps every catch-at-length expected composition count that has an observation.
  expect_false(anyNA(counts[["estimated"]][!is.na(counts[["observed"]])]))
})

## Error handling ----
test_that("`initialize_fims()` refuses observed length compositions in a year with 0 catch", {
  zero_catch_data <- cal_data
  zero_catch_data[["observed"]][
    zero_catch_data[["fleet"]] == "pot_fleet" &
      zero_catch_data[["type"]] %in% c("catch_retained", "catch_discarded") &
      zero_catch_data[["timing"]] == 2002
  ] <- 0
  zero_catch_frame <- FIMSFrame(zero_catch_data)
  zero_catch_params <- setup_default_parameters(
    zero_catch_frame,
    model_type = "CatchAtLength"
  )

  #' @description Test that initialize_fims() aborts when a fishing fleet has observed length_comp data in a year where all catch is 0.
  expect_error(
    object = initialize_fims(zero_catch_params, zero_catch_frame),
    regexp = "has observed.*length_comp.*data in year.*2002.*when catch is 0"
  )
})

test_that("`FIMSFrame()` and `initialize_fims()` refuse inconsistent catch-at-length inputs", {
  molt_model_years <- dplyr::filter(
    cal_data,
    !(type == "terminal_molt_probability_at_length" &
      timing > max(cal_years))
  )
  #' @description Test that FIMSFrame() errors, rather than dropping the last catch year, when terminal molt rows stop at the last catch year.
  expect_error(
    object = FIMSFrame(molt_model_years),
    regexp = "has catch in.*after.*the last model year"
  )

  molt_missing_year <- dplyr::filter(
    cal_data,
    !(type == "terminal_molt_probability_at_length" &
      timing == cal_years[2])
  )
  #' @description Test that FIMSFrame() errors when terminal molt rows skip a model year.
  expect_error(
    object = FIMSFrame(molt_missing_year),
    regexp = "terminal_molt_probability_at_length.*has rows for years"
  )

  stage_weights <- cal_data
  is_immature_weight <- stage_weights[["type"]] == "weight_at_length" &
    stage_weights[["maturity"]] %in% "immature"
  stage_weights[["observed"]][is_immature_weight] <-
    0.5 * stage_weights[["observed"]][is_immature_weight]
  stage_weight_frame <- FIMSFrame(stage_weights)
  #' @description Test that initialize_fims() errors when immature and mature weight at length differ.
  expect_error(
    object = initialize_fims(
      setup_default_parameters(stage_weight_frame, model_type = "CatchAtLength"),
      stage_weight_frame
    ),
    regexp = "different.*weight_at_length"
  )

  estimated_discard_mortality <- cal_default_parameters |>
    dplyr::mutate(
      estimation_type = dplyr::if_else(
        label == "discard_mortality", "fixed_effects", estimation_type
      )
    )
  #' @description Test that initialize_fims() errors when discard mortality is estimated.
  expect_error(
    object = initialize_fims(estimated_discard_mortality, cal_frame),
    regexp = "discard_mortality.*must be.*constant"
  )
})

test_that("`catch_at_length()` stops when growth returns a growth transition of the wrong size", {
  # Linear gamma growth that drops the last column of the transition, so
  # fish cannot molt into the largest length bin. Without the check, the
  # model recycles the 3 columns over the 4 bins with no error.
  short_transition <- FIMS:::growth_modules
  short_transition[["LinearGammaIncrement"]][["evaluate"]] <- function(...) {
    growth <- FIMS:::linear_gamma_increment_growth(...)
    growth[["growth_transition"]] <- growth[["growth_transition"]][, 1:3]
    growth
  }
  local_mocked_bindings(growth_modules = short_transition)
  #' @description Test that the catch-at-length model stops when the growth transition does not have 1 row and 1 column per population length bin.
  expect_error(
    object = cal_default_parameters |>
      initialize_fims(data = cal_frame) |>
      fit_fims(optimize = FALSE),
    regexp = "growth_transition.*of size 4 x 3"
  )
})
